        uint256 basisPoints;
    }
    Recipient[] public recipients;
    uint256 public totalBasisPoints;

    event PaymentTokenAdded(address token);
    event PaymentTokenRemoved(address token);
    event RecipientAdded(address wallet, uint256 basisPoints);
    event RecipientRemoved(address wallet);
    event TokensPurchased(address buyer, uint256 usdAmount, uint256 tokens);
    event TokensClaimed(address claimer, uint256 amount);
    event FundsWithdrawn(address token, uint256 amount, address recipient);
    event TokensBurned(uint256 amount);

    constructor(
        IERC20 _saleToken,
        uint256 _startTime,
        address initialOwner
    ) Ownable(initialOwner) {
        require(
            address(_saleToken) != address(0),
            "Invalid sale token address"
        );

        saleToken = _saleToken;
        startTime = _startTime;
    }

    // **Function to get the total number of tokens sold**
    function totalSoldTokens() public view returns (uint256) {
        uint256 totalSold = 0;
        for (uint256 i = 1; i <= TOTAL_STAGES; i++) {
            totalSold += tokensSoldPerStage[i];
        }
        return totalSold;
    }

    // **Function to get the total token supply in the presale contract**
    function totalSupply() public view returns (uint256) {
        return saleToken.balanceOf(address(this));
    }

    // **Add a payment token and its Chainlink price feed**
    function addPaymentToken(
        address token,
        address priceFeed,
        uint8 decimals
    ) external onlyOwner {
        require(priceFeed != address(0), "Invalid price feed address");
        require(decimals > 0, "Invalid token decimals");

        if (token == address(0)) {
            require(
                !supportedPaymentTokens[token],
                "Native token already added"
            );
            supportedPaymentTokens[token] = true;
            priceFeeds[token] = AggregatorV3Interface(priceFeed);
            tokenDecimals[token] = decimals;
        } else {
            require(token != address(0), "Invalid token address");
            require(!supportedPaymentTokens[token], "Token already supported");
            supportedPaymentTokens[token] = true;
            priceFeeds[token] = AggregatorV3Interface(priceFeed);
            tokenDecimals[token] = decimals;
        }

        emit PaymentTokenAdded(token);
    }

    // **Remove a payment token**
    function removePaymentToken(address token) external onlyOwner {
        require(supportedPaymentTokens[token], "Token not supported");

        supportedPaymentTokens[token] = false;
        delete priceFeeds[token];
        delete tokenDecimals[token];

        emit PaymentTokenRemoved(token);
    }

    // **Modify the presale start time**
    function setStartTime(uint256 newStartTime) external onlyOwner {
        startTime = newStartTime;
    }

    // **Add or update a recipient**
    function addRecipient(address wallet, uint256 basisPoints)
        external
        onlyOwner
    {
        require(wallet != address(0), "Invalid wallet address");
        require(basisPoints > 0, "Basis points must be greater than 0");

        uint256 newTotalBasisPoints = totalBasisPoints + basisPoints;

        for (uint256 i = 0; i < recipients.length; i++) {
            if (recipients[i].wallet == wallet) {
                newTotalBasisPoints -= recipients[i].basisPoints;
                recipients[i].basisPoints = basisPoints;
                totalBasisPoints = newTotalBasisPoints;

                require(
                    totalBasisPoints <= 10000,
                    "Total allocation exceeds 100%"
                );
                emit RecipientAdded(wallet, basisPoints);
                return;
            }
        }

        require(newTotalBasisPoints <= 10000, "Total allocation exceeds 100%");
        recipients.push(Recipient(wallet, basisPoints));
        totalBasisPoints = newTotalBasisPoints;
        emit RecipientAdded(wallet, basisPoints);
    }

    // **Remove a recipient**
    function removeRecipient(address wallet) external onlyOwner {
        require(wallet != address(0), "Invalid wallet address");

        for (uint256 i = 0; i < recipients.length; i++) {
            if (recipients[i].wallet == wallet) {
                totalBasisPoints -= recipients[i].basisPoints;
                recipients[i] = recipients[recipients.length - 1];
                recipients.pop();
                emit RecipientRemoved(wallet);
                return;
            }
        }
        revert("Recipient not found");
    }

    // **Contribute using a payment token**
    function contribute(address paymentToken, uint256 amount) external payable {
        require(
            supportedPaymentTokens[paymentToken],
            "Unsupported payment token"
        );
        require(block.timestamp >= startTime, "Presale has not started");

        uint256 tokenPriceUSD = getCurrentPriceUSD();
        uint256 usdRate = getTokenUSDPrice(paymentToken);
        uint256 usdAmount;

        if (paymentToken == address(0)) {
            usdAmount = (msg.value * usdRate) / 1e18;
        } else {
            uint8 decimals = tokenDecimals[paymentToken];
            uint256 normalizedAmount = _normalizeTo18Decimals(amount, decimals);
            usdAmount = (normalizedAmount * usdRate) / 1e18;
        }

        uint256 tokenAmount = (usdAmount * 1e18) / tokenPriceUSD;

        require(
            saleToken.balanceOf(address(this)) >= tokenAmount,
            "Not enough tokens available"
        );

        // If the paymentToken is ERC20, transfer tokens after checks
        if (paymentToken != address(0)) {
            IERC20(paymentToken).transferFrom(
                msg.sender,
                address(this),
                amount
            );
        }

        // Distribute funds
        _distributeFunds(
            paymentToken == address(0) ? msg.value : amount,
            paymentToken
        );

        // Update user contributions and pending tokens
        contributions[msg.sender] += usdAmount;
        pendingTokens[msg.sender] += tokenAmount;
        totalRaisedUSD += usdAmount;

         uint256 currentStage = getCurrentStage();
        tokensSoldPerStage[currentStage] += tokenAmount;

        emit TokensPurchased(msg.sender, usdAmount, tokenAmount);
    }

    // **Distribute funds to recipients**
    function _distributeFunds(uint256 amount, address token) internal {
        for (uint256 i = 0; i < recipients.length; i++) {
            uint256 share = (amount * recipients[i].basisPoints) / 10000;
            if (token == address(0)) {
                payable(recipients[i].wallet).transfer(share);
            } else {
                IERC20(token).transfer(recipients[i].wallet, share);
            }
        }
    }

    // **Get the current stage**
    function getCurrentStage() public view returns (uint256) {
        if (block.timestamp < startTime) return 0;
        uint256 elapsedTime = block.timestamp - startTime;
        uint256 stage = (elapsedTime / STAGE_DURATION) + 1;
        return stage > TOTAL_STAGES ? TOTAL_STAGES : stage;
    }

    // **Get the current token price in USD**
    function getCurrentPriceUSD() public view returns (uint256) {
        uint256 stage = getCurrentStage();
        return START_PRICE_USD + (PRICE_INCREMENT_USD * (stage - 1));
    }

    // **Get USD price of a payment token**
    function getTokenUSDPrice(address token) public view returns (uint256) {
        AggregatorV3Interface priceFeed = priceFeeds[token];
        (, int256 price, , , ) = priceFeed.latestRoundData();
        require(price > 0, "Invalid price");
        return uint256(price * 1e10);
    }

    // **Claim tokens after presale**
    function claimTokens() external {
        require(isClaimingEnabled, "Claiming is not enabled");
        uint256 amount = pendingTokens[msg.sender];
        require(amount > 0, "No tokens to claim");
        pendingTokens[msg.sender] = 0;
        saleToken.transfer(msg.sender, amount);
        emit TokensClaimed(msg.sender, amount);
    }

    // **Enable or disable claiming**
    function setClaimingEnabled(bool enabled) external onlyOwner {
        isClaimingEnabled = enabled;
    }

    // **Withdraw funds**
    function withdrawFunds(address token) external onlyOwner {
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No tokens to withdraw");
        IERC20(token).transfer(owner(), balance);
        emit FundsWithdrawn(token, balance, owner());
    }

    // **Withdraw native funds**
    function withdrawNative() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No native tokens to withdraw");
        payable(owner()).transfer(balance);
    }

    // **Burning tokens function**
    function burn(uint256 amount) external onlyOwner {
        require(amount > 0, "Amount must be greater than 0");
        require(
            saleToken.balanceOf(address(this)) >= amount,
            "Insufficient tokens in contract"
        );

        // Call the burn function of the saleToken
        ERC20Burnable(address(saleToken)).burn(amount);

        emit TokensBurned(amount);
    }

    // **Normalize token decimals to 18**
    function _normalizeTo18Decimals(uint256 amount, uint8 decimals)
        internal
        pure
        returns (uint256)
    {
        return
            decimals < 18
                ? amount * (10**(18 - decimals))
                : amount / (10**(decimals - 18));
    }

    receive() external payable {}
}
